package local.skyfamily;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
public class PolishActivity extends RefreshActivity {
 PdfPane pdf;String projectId="",projectName="";final Handler autosave=new Handler();final ExecutorService projectIO=Executors.newSingleThreadExecutor();
 final Runnable checkpoint=()->captureProject(false);
 @Override void page(String title){if(!rebuilding){autosave.removeCallbacks(checkpoint);if(currentArt!=null)captureProject(false);projectId="";projectName="";}if(pdf!=null){pdf.close();pdf=null;}super.page(title);}
 @Override void projectsEntry(){projects();}
 @Override void importBook(){new android.app.AlertDialog.Builder(this).setTitle("Add to your bookshelf").setItems(new String[]{"EPUB / text book","PDF document"},(dialog,which)->{if(which==0)super.importBook();else{new android.app.AlertDialog.Builder(this).setTitle("Legacy PDF support").setMessage("This Android 4.2-compatible PDF engine is old. Open trusted documents only. PDF editing and form filling are not included.").setPositiveButton("Choose PDF",(d,w)->{Intent i=new Intent(Intent.ACTION_GET_CONTENT);i.setType("application/pdf");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(Intent.createChooser(i,"Import PDF"),702);}catch(Exception e){toast("Install a file picker first");}}).setNegativeButton("Cancel",null).show();}}).show();}
 @Override protected void onActivityResult(int request,int result,Intent data){if(request!=702){super.onActivityResult(request,result,data);return;}if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();String title="PDF document";try(Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())title=cursor.getString(0);}catch(Exception ignored){}final String fallback=title==null?"PDF document":title;final int stamp=revision;text("Importing PDF...");work(()->{File dir=bookDir();long used=0;File[] files=dir.listFiles();if(files!=null)for(File f:files)used+=f.length();if(index().length()>=100)throw new IOException("Bookshelf limit reached");String id=UUID.randomUUID().toString();File file=new File(dir,id+".pdf");boolean saved=false;try{try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException("Cannot open selected file");byte[] b=new byte[16384];long size=0;int n;while((n=in.read(b))!=-1){size+=n;if(size>50000000L||used+size>250000000L)throw new IOException("PDF exceeds import storage limits");out.write(b,0,n);}}PdfPages.Page cover=PdfPages.render(this,file,0,240,320);try(FileOutputStream out=new FileOutputStream(new File(dir,id+".png"))){cover.image.compress(Bitmap.CompressFormat.PNG,100,out);}cover.image.recycle();JSONObject record=new JSONObject().put("id",id).put("file",file.getName()).put("title",cover.title.trim().isEmpty()?fallback:cover.title).put("author",cover.author).put("format","PDF").put("pages",cover.count);saved=true;ui.post(()->{JSONArray books=index();books.put(record);save("books.index",books.toString());toast("PDF imported with cover thumbnail");if(stamp==revision)bookshelf();});}finally{if(!saved){file.delete();new File(dir,id+".png").delete();}}});}
 @Override void openBook(JSONObject book){if(!book.optString("format").equals("PDF")){super.openBook(book);return;}page(book.optString("title"));pdf=new PdfPane(this,book);setContentView(pdf);immersive();}
 @Override void renderStudio(){super.renderStudio();if(currentArt!=null)currentArt.setOnTouchListener((view,event)->{if(event.getAction()==MotionEvent.ACTION_UP||event.getAction()==MotionEvent.ACTION_CANCEL){autosave.removeCallbacks(checkpoint);autosave.postDelayed(checkpoint,1200);}return false;});}
 @Override void saveArtwork(){captureProject(true);}
 void captureProject(boolean report){if(currentArt==null)return;Bitmap paint=null,preview=null;try{if(projectId.isEmpty())projectId=UUID.randomUUID().toString();if(projectName.isEmpty())projectName=(artColour?"Colouring":"Drawing")+" / "+new java.text.SimpleDateFormat("d MMM HH:mm",Locale.getDefault()).format(new Date());JSONObject meta=new JSONObject().put("id",projectId).put("title",projectName).put("colouring",artColour).put("template",currentArt.template).put("width",currentArt.width).put("alpha",currentArt.alpha).put("color",currentArt.color).put("eraser",currentArt.erase).put("turns",quarterTurns).put("updated",System.currentTimeMillis());paint=currentArt.paintLayer.copy(Bitmap.Config.ARGB_8888,false);Bitmap exported=currentArt.export();preview=Bitmap.createScaledBitmap(exported,240,150,true);if(preview!=exported)exported.recycle();final Bitmap layer=paint,thumb=preview;projectIO.submit(()->{try{ArtFiles.save(this,meta,layer,thumb);if(report)ui.post(()->toast("Editable project saved"));}catch(Exception e){ui.post(()->toast("Project save failed: "+e.getMessage()));}finally{layer.recycle();thumb.recycle();}});}catch(Exception e){if(paint!=null)paint.recycle();if(preview!=null)preview.recycle();toast("Could not snapshot artwork: "+e.getMessage());}}
 @Override void artistTools(){if(currentArt==null)return;new android.app.AlertDialog.Builder(this).setTitle(projectName.isEmpty()?"Creative studio":projectName).setItems(new String[]{"Brush, colours and page tools","Save editable project","Rename project","Saved project gallery","Export PNG image"},(dialog,which)->{if(which==0)super.artistTools();if(which==1)captureProject(true);if(which==2){EditText name=new EditText(this);name.setText(projectName);new android.app.AlertDialog.Builder(this).setTitle("Project name").setView(name).setPositiveButton("Save",(d,w)->{String value=name.getText().toString().trim();if(value.isEmpty()){toast("Enter a name");return;}projectName=value.substring(0,Math.min(100,value.length()));captureProject(true);}).setNegativeButton("Cancel",null).show();}if(which==3)projects();if(which==4)super.saveArtwork();}).show();}
 @Override void toolAction(LinearLayout parent,String title,Runnable action){super.toolAction(parent,title.equals("Save PNG")?"Save editable project":title,action);}
 void projects(){page("Your art projects");button("New drawing",()->drawing(false));button("New colouring page",()->drawing(true));text("Editable saves include paint, colouring-page identity, tools and canvas rotation. Tap to continue; long-press to remove.");final int stamp=revision;projectIO.submit(()->{ArrayList<JSONObject> list=ArtFiles.list(this);ui.post(()->{if(stamp!=revision)return;if(list.isEmpty())text("Your saved projects will appear here.");LinearLayout row=null;int count=0,columns=getResources().getConfiguration().screenWidthDp>=900?3:2;for(JSONObject meta:list){if(count%columns==0){row=new LinearLayout(this);body.addView(row);}LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(12),dp(12),dp(12),dp(12));card.setBackground(press(surface));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(210),1);cp.setMargins(dp(5),dp(5),dp(5),dp(5));row.addView(card,cp);ImageView image=new ImageView(this);image.setImageBitmap(BitmapFactory.decodeFile(new File(ArtFiles.dir(this),meta.optString("id")+".thumb.png").getPath()));image.setScaleType(ImageView.ScaleType.FIT_CENTER);card.addView(image,new LinearLayout.LayoutParams(-1,dp(135)));TextView title=new TextView(this);title.setText(meta.optString("title"));title.setTextColor(fg);title.setTextSize(17);title.setMaxLines(2);card.addView(title);TextView kind=new TextView(this);kind.setText(meta.optBoolean("colouring")?"Colouring / editable":"Drawing / editable");kind.setTextColor(muted);card.addView(kind);card.setOnClickListener(v->resumeProject(meta.optString("id")));card.setOnLongClickListener(v->{new android.app.AlertDialog.Builder(this).setMessage("Delete this saved project?").setPositiveButton("Delete",(d,w)->{projectIO.submit(()->{ArtFiles.remove(this,meta.optString("id"));ui.post(()->projects());});}).setNegativeButton("Cancel",null).show();return true;});count++;}if(row!=null&&count%columns!=0)for(int i=count%columns;i<columns;i++)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));});});}
 void resumeProject(String id){page("Opening project");final int stamp=revision;projectIO.submit(()->{try{JSONObject meta=ArtFiles.metadata(this,id);Bitmap paint=ArtFiles.paint(this,id);ui.post(()->{if(stamp!=revision){paint.recycle();return;}page("Creative studio");projectId=id;projectName=meta.optString("title");artColour=meta.optBoolean("colouring");currentArt=new Studio(artColour);currentArt.paintLayer.recycle();currentArt.paintLayer=paint;currentArt.paintCanvas=new Canvas(paint);currentArt.template=meta.optInt("template");currentArt.width=(float)meta.optDouble("width",8);currentArt.alpha=meta.optInt("alpha",255);currentArt.color=meta.optInt("color",Color.BLACK);currentArt.erase=meta.optBoolean("eraser");quarterTurns=meta.optInt("turns")%4;artFull=true;renderStudio();});}catch(Exception e){ui.post(()->toast("Could not reopen project: "+e.getMessage()));}});}
 @Override public void onBackPressed(){if(pdf!=null)bookshelf();else super.onBackPressed();}
 @Override protected void onPause(){autosave.removeCallbacks(checkpoint);if(currentArt!=null)captureProject(false);super.onPause();}
 @Override protected void onDestroy(){autosave.removeCallbacksAndMessages(null);if(pdf!=null)pdf.close();projectIO.shutdown();super.onDestroy();}
}
